def esperado(n):
    linhas = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            linhas.append("FizzBuzz")
        elif i % 3 == 0:
            linhas.append("Fizz")
        elif i % 5 == 0:
            linhas.append("Buzz")
        else:
            linhas.append(str(i))
    return linhas

for n in (5, 31):
    r = rodar([str(n)])
    saida_igual(r, esperado(n))

