secreto = int(input("Número secreto: "))
tentativas = 0
while True:
    chute = int(input("Seu chute: "))
    tentativas += 1
    if chute == secreto:
        break
    if secreto > chute:
        print("Maior!")
    else:
        print("Menor!")
if tentativas == 1:
    print("Acertou de primeira!")
else:
    print(f"Acertou em {tentativas} tentativas!")
